// runOnceForAllItems: pairs LLM outputs with original shorts from Merge Transcript by index.
const llmOutputs = $input.all();
const shorts = $('Merge Transcript').all();

return llmOutputs.map(function(item, i) {
    const j = item.json;
    const short = shorts[i] ? shorts[i].json : {};

    let aiText = '';
    if (j.output && Array.isArray(j.output) && j.output[0]?.content && Array.isArray(j.output[0].content)) {
        aiText = j.output[0].content[0].text || '';
    } else if (j.content && Array.isArray(j.content)) {
        aiText = j.content[0]?.text || '';
    } else if (j.text) {
        aiText = j.text;
    } else if (j.message?.content) {
        aiText = j.message.content;
    }

    if (typeof aiText !== 'string') {
        aiText = JSON.stringify(aiText || '');
    }

    let score = {};
    const match = aiText.match(/\{[\s\S]*\}/);
    if (match) {
        try { score = JSON.parse(match[0]); } catch(e) {}
    }

    return {
        json: {
            video_id: short.video_id || '',
            url: short.url || '',
            title: short.title || '',
            channel_title: short.channel_title || '',
            duration: short.duration || null,
            theme: short.theme || '',
            transcript: short.transcript || null,
            score: typeof score.score === 'number' ? score.score : 0,
            reason: score.reason || '',
            should_rewrite: score.should_rewrite === true
        }
    };
});

const data = $input.all()[0]?.json;

if (!data || !data.title || data.title.length === 0) {
    return [{ json: { text: "🔍 Релевантных шортсов по заданной тематике не найдено 😔" } }];
}

const messages = [];
let part = 1;
let currentMessage = `🎬 *Найдены релевантные шортсы! (Часть ${part})*\n\n`;

for (let i = 0; i < data.title.length; i++) {
    const title = String(data.title[i]).replace(/[*_\[\]`]/g, '').substring(0, 80);
    const url = data.url[i];
    const score = data.score[i];
    const reason = String(data.reason[i] || '').replace(/[*_\[\]`]/g, '').substring(0, 180);
    const channel = String(data.channel_title[i] || 'Unknown').replace(/[*_\[\]`]/g, '');
    const duration = data.duration[i];

    const block = `✅ *${title}*\n📺 ${channel} | ⏱ ${duration}s | 🎯 Score: ${score}/10\n🔗 ${url}\n💬 ${reason}\n\n`;

    if ((currentMessage.length + block.length) > 3800) {
        messages.push({ json: { text: currentMessage } });
        part++;
        currentMessage = `🎬 *Продолжение (Часть ${part}):*\n\n`;
    }
    currentMessage += block;
}

if (currentMessage.replace(/\*.*?\*/g, '').trim().length > 0) {
    messages.push({ json: { text: currentMessage } });
}

return messages;

// runOnceForAllItems: receives all HTTP responses at once
// One item per query -> we enrich each and return N items for Split Out
const allItems = $input.all();

// Theme is the same for all queries (comes from the original topic)
const theme = $('Parse Queries').first().json.theme || '';

const results = [];
for (const item of allItems) {
    const data = item.json;
    const query = data.query || '';

    const enrichedShorts = (data.shorts || []).map(function(s) {
        return {
            video_id: s.video_id || '',
            url: s.url || '',
            title: s.title || 'No title',
            channel_id: s.channel_id || null,
            channel_title: s.channel_title || null,
            duration: s.duration || null,
            search_query: query,
            theme: theme
        };
    });

    results.push({ json: { shorts: enrichedShorts } });
}

return results.length > 0 ? results : [{ json: { shorts: [] } }];

// runOnceForAllItems: pairs transcript responses with original shorts by index.
// HTTP Request preserves order, so index i in transcripts == index i in Split Shorts.
const transcripts = $input.all();
const shorts = $('Split Shorts').all();

return transcripts.map(function(item, i) {
    const short = shorts[i] ? shorts[i].json : {};
    const t = item.json;
    return {
        json: {
            video_id: short.video_id || '',
            url: short.url || '',
            title: short.title || 'No title',
            channel_id: short.channel_id || null,
            channel_title: short.channel_title || null,
            duration: short.duration || null,
            search_query: short.search_query || '',
            theme: short.theme || '',
            transcript: t.transcript || null,
            transcript_source: t.source || null,
            transcript_error: t.error || null
        }
    };
});
